import{categories,filterCases,validateCase,artifactLabel}from'./catalog-core.mjs?v=threejs-1';const $=s=>document.querySelector(s),grid=$('#grid'),dialog=$('#detail');let items=[],category='all',query='';function el(t,c,x){const e=document.createElement(t);if(c)e.className=c;if(x!==undefined)e.textContent=x;return e}const cat=id=>categories.find(c=>c[0]===id)?.[1]||id;function close(){dialog.close();document.body.style.overflow=''}function render(){let list=filterCases(items,{category,query});grid.replaceChildren();$('#empty').hidden=!!list.length;$('#result-info').textContent=`${String(list.length).padStart(2,'0')} 件真实作品 · ${cat(category)}`;for(const c of list){let b=el('button','card');b.type='button';b.setAttribute('aria-label',`查看案例：${c.title}`);let v=el('div','card-visual'),i=el('img');i.src=c.poster;i.alt=c.title;i.loading='lazy';i.width=1200;i.height=800;v.append(i,el('span','num',String(items.indexOf(c)+1).padStart(2,'0')),el('span','arrow','↗'));let m=el('div','card-meta');m.append(el('span','',c.useCase),el('span','',cat(c.category)+' / '+c.engine));let tags=el('div','tags');c.tags.forEach(t=>tags.append(el('span','',t)));b.append(v,m,el('h3','',c.title),el('p','',c.summary),tags);b.onclick=()=>open(c);grid.append(b)}for(let b of $('#filters').children)b.setAttribute('aria-pressed',String(b.dataset.category===category))}function open(c){let body=$('#detail-body');body.replaceChildren();let i=el('img','detail-img');i.src=c.poster;i.alt=c.title;let con=el('div','detail-content'),h=el('h2','',c.title);h.id='detail-title';con.append(el('span','detail-category',c.useCase+' · '+cat(c.category)),h,el('p','',c.summary));let dl=el('dl');for(let[k,v]of[['制作工具',c.engine],['模型信息',c.model],['真实验证',c.verification],['素材与权利',c.rights]])dl.append(el('dt','',k),el('dd','',v));let ol=el('ol');c.steps.forEach(s=>ol.append(el('li','',s)));con.append(dl,el('h3','','复现与探索'),ol);let fs=el('div','files');for(let [label,path]of[[artifactLabel(c),c.artifact],['源码或提示词',c.source],['来源与验证',c.provenance],...(c.preview?[['播放静音技术预览',c.preview]]:[]),...(c.offline?[['离线单文件 HTML',c.offline]]:[])]){let a=el('a','',label);a.href=path;a.target='_blank';a.rel='noopener';fs.append(a)}con.append(fs);body.append(i,con);dialog.showModal();document.body.style.overflow='hidden'}$('#close-detail').onclick=close;dialog.oncancel=()=>document.body.style.overflow='';dialog.onclick=e=>{if(e.target===dialog){let r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}};$('#search').oninput=e=>{query=e.target.value;render()};$('#clear').onclick=()=>{query='';category='all';$('#search').value='';render()};try{let res=await fetch('cases.json',{cache:'no-store'});if(!res.ok)throw Error('无法读取清单');let data=await res.json();items=data.cases;for(let c of items)if(validateCase(c).length)throw Error('案例资料不完整');$('#total').textContent=String(items.length).padStart(2,'0');$('#hero-image').src=items[0].poster;$('#hero-image').alt=items[0].title;$('#hero-title').textContent=items[0].title;$('#hero-category').textContent=cat(items[0].category)+' ↗';if(data.repository){let a=el('a','', '查看 GitHub 仓库 ↗');a.href=data.repository;a.target='_blank';a.rel='noopener';$('#repo-link').replaceChildren(a)}for(let[id,label]of categories){let b=el('button','',label);b.type='button';b.dataset.category=id;b.onclick=()=>{category=id;render()};$('#filters').append(b)}render()}catch(e){$('#result-info').textContent='案例清单暂时无法读取。请通过静态服务器打开，或阅读仓库 README。';console.error(e)}
